-- 2026-10-16 owner: B2 Muendlich Teil 3 'Buchmesse' (in telccfree, missing here) -> Tunisia list. ROLLBACK: delete from public.muendlich_materials where teil = 3 and level = 'TELC_B2' and title = 'Buchmesse im Kulturzentrum mitplanen';
insert into public.muendlich_materials (teil, category, level, title, body_text, theme_category, difficulty_level, position, sort_order, source_pdf, is_unassigned_center, is_free_sample, speaking_toolbox)
select 3, 'themen', 'TELC_B2', $q$Buchmesse im Kulturzentrum mitplanen$q$, $q$An einem Kulturzentrum in Ihrer Stadt wird eine Buchmesse stattfinden. Sie wollen bei der Planung helfen. Überlegen Sie, was Sie tun können. Denken Sie beispielsweise an Informationsmaterial oder Poster.$q$, 'Medien', 'B2', 59, 0, 'telccfree.com (B2 Sprechen Teil 3, b2-s3-buchmesse)', false, false, $q${"struktur":[{"key":"start","demo":{"frage":"Wie du weißt, soll im Kulturzentrum unserer Stadt eine Buchmesse stattfinden, und wir möchten bei der Planung helfen. Wo fangen wir an?","antwort":"Ich denke, wir sollten zuerst überlegen, wie wir die Leute über die Messe informieren."}},{"key":"werbung","demo":{"frage":"Wie könnten wir möglichst viele Besucher erreichen?","antwort":"Wir könnten Poster in Schulen, Bibliotheken und Buchhandlungen aufhängen und die Messe in sozialen Medien ankündigen.","reaktion":"Das halte ich für sinnvoll, weil wir dadurch viele unterschiedliche Leute ansprechen."}},{"key":"informationsmaterial","demo":{"frage":"Brauchen wir auch Informationsmaterial?","antwort":"Ja, ein Flyer mit Datum, Uhrzeit und den wichtigsten Programmpunkten wäre hilfreich.","reaktion":"Gute Idee, dann wissen die Besucher sofort, was angeboten wird."}},{"key":"programm","demo":{"frage":"Was für ein Programm könnten wir organisieren?","antwort":"Vielleicht Lesungen von verschiedenen Autoren und einen Kinderbereich, in dem man kurze Geschichten vorliest.","reaktion":"Das finde ich gut, so ist für jede Altersgruppe etwas dabei."}},{"key":"experten","demo":{"frage":"Sollten wir auch eine Signierstunde mit einem Autor organisieren?","antwort":"Das wäre attraktiv, aber wir müssten den Autor rechtzeitig kontaktieren.","reaktion":"Stimmt, das sollten wir gleich als Erstes klären."}},{"key":"stände","demo":{"frage":"Was ist mit den Ständen?","antwort":"Wir könnten lokale Buchhandlungen und einige Verlage einladen und einen kleinen Bereich für gebrauchte Bücher einrichten.","reaktion":"Gute Idee, so gibt es für jedes Budget etwas."}},{"key":"orientierung","demo":{"frage":"Woran sollten wir bei der Orientierung der Besucher denken?","antwort":"Ein Lageplan und kleine Wegweiser wären hilfreich, dazu ein Informationsstand am Eingang.","reaktion":"Das halte ich für sehr praktisch."}},{"key":"helfer","demo":{"frage":"Wie viele Helfer brauchen wir?","antwort":"Einige am Eingang, zwei am Informationsstand und zusätzliche Personen für das Kinderprogramm.","reaktion":"Das klingt nach einer vernünftigen Lösung."}},{"key":"aufgabenverteilung","demo":{"frage":"Wie könnten wir die Aufgaben möglichst effizient aufteilen?","antwort":"Ich kann Poster und Flyer vorbereiten. Würdest du dann das Kulturzentrum kontaktieren und nach dem Raumplan fragen?","reaktion":"Ja, das übernehme ich gerne."}},{"key":"abschluss","demo":{"frage":"Dann können wir festhalten, dass wir mit Werbung, Lesungen, Kinderbereich, Ständen und einem Lageplan planen.","antwort":"Genau. So haben wir Werbung, Programm, Stände und Organisation abgedeckt.","reaktion":"Perfekt, dann haben wir einen guten Plan."}}],"erklaerung":{"worauf_achten":["Werbung, Programm, Stände und Organisation sollten alle vorkommen.","Denken Sie auch an Informationsmaterial wie Poster und Flyer, so wie in der Aufgabe genannt.","Ein Kinderprogramm und ein Lageplan machen die Messe für mehr Besucher attraktiv."],"worum_geht_es":"An einem Kulturzentrum in Ihrer Stadt wird eine Buchmesse stattfinden. Sie und Ihr Gesprächspartner / Ihre Gesprächspartnerin wollen bei der Planung helfen.","wichtige_punkte":["Wie machen wir Werbung (Poster, Flyer, soziale Medien)?","Welches Programm bieten wir an (Lesungen, Kinderbereich, Signierstunde)?","Wer stellt aus (Buchhandlungen, Verlage, gebrauchte Bücher)?","Wer übernimmt welche Aufgabe (Helfer, Technik, Kontakt zum Kulturzentrum)?"],"worum_geht_es_ar":"ستُقام في مركز ثقافي بمدينتكم معرضٌ للكتاب. أنتم وشريككم في الحوار تريدان المساعدة في التخطيط له.","was_wird_erwartet":"Sie überlegen gemeinsam, was Sie tun können: Werbung, Informationsmaterial, Programm, Stände und Organisation, und einigen sich auf einen Plan.","wichtige_punkte_ar":["كيف نُعلن عن المعرض (ملصقات، منشورات، وسائل التواصل)؟","ما البرنامج الذي نقدّمه (قراءات، ركن للأطفال، جلسة توقيع)؟","من سيشارك بأجنحة (مكتبات، دور نشر، كتب مستعملة)؟","من يتولّى أي مهمة (مساعدون، تقنيات، الاتصال بالمركز الثقافي)؟"],"was_wird_erwartet_ar":"تفكّران معًا فيما يمكنكما فعله: الإعلان، المواد المعلوماتية، البرنامج، الأجنحة والتنظيم، ثم تتفقان على خطة."},"wortschatz":{"verben":["ankündigen","einladen","vorlesen","aufhängen","organisieren"],"woerter":["die Buchmesse","die Lesung","die Signierstunde","der Stand","der Lageplan"],"adjektive":["abwechslungsreich","attraktiv","übersichtlich","kinderfreundlich"]},"wortschatz_ar":{"verben":["يُعلن عن","يدعو","يقرأ بصوت عالٍ","يعلّق","ينظّم"],"woerter":["معرض الكتاب","جلسة قراءة","جلسة توقيع","الجناح","مخطط الموقع"],"adjektive":["متنوّع","جذّاب","واضح ومنظّم","مناسب للأطفال"]},"beispieldialog":[{"text":"Wie du weißt, soll im Kulturzentrum unserer Stadt eine Buchmesse stattfinden, und wir möchten bei der Planung helfen. Wo fangen wir an?","section":"start","speaker":"A"},{"text":"Ich denke, wir sollten zuerst überlegen, wie wir die Leute über die Messe informieren.","section":"start","speaker":"B"},{"text":"Wie könnten wir möglichst viele Besucher erreichen?","section":"werbung","speaker":"A"},{"text":"Wir könnten Poster in Schulen, Bibliotheken und Buchhandlungen aufhängen und die Messe in sozialen Medien ankündigen.","section":"werbung","speaker":"B"},{"text":"Das halte ich für sinnvoll, weil wir dadurch viele unterschiedliche Leute ansprechen.","section":"werbung","speaker":"A"},{"text":"Brauchen wir auch Informationsmaterial?","section":"informationsmaterial","speaker":"A"},{"text":"Ja, ein Flyer mit Datum, Uhrzeit und den wichtigsten Programmpunkten wäre hilfreich.","section":"informationsmaterial","speaker":"B"},{"text":"Gute Idee, dann wissen die Besucher sofort, was angeboten wird.","section":"informationsmaterial","speaker":"A"},{"text":"Was für ein Programm könnten wir organisieren?","section":"programm","speaker":"B"},{"text":"Vielleicht Lesungen von verschiedenen Autoren und einen Kinderbereich, in dem man kurze Geschichten vorliest.","section":"programm","speaker":"A"},{"text":"Das finde ich gut, so ist für jede Altersgruppe etwas dabei.","section":"programm","speaker":"B"},{"text":"Sollten wir auch eine Signierstunde mit einem Autor organisieren?","section":"experten","speaker":"A"},{"text":"Das wäre attraktiv, aber wir müssten den Autor rechtzeitig kontaktieren.","section":"experten","speaker":"B"},{"text":"Stimmt, das sollten wir gleich als Erstes klären.","section":"experten","speaker":"A"},{"text":"Was ist mit den Ständen?","section":"stände","speaker":"B"},{"text":"Wir könnten lokale Buchhandlungen und einige Verlage einladen und einen kleinen Bereich für gebrauchte Bücher einrichten.","section":"stände","speaker":"A"},{"text":"Gute Idee, so gibt es für jedes Budget etwas.","section":"stände","speaker":"B"},{"text":"Woran sollten wir bei der Orientierung der Besucher denken?","section":"orientierung","speaker":"A"},{"text":"Ein Lageplan und kleine Wegweiser wären hilfreich, dazu ein Informationsstand am Eingang.","section":"orientierung","speaker":"B"},{"text":"Das halte ich für sehr praktisch.","section":"orientierung","speaker":"A"},{"text":"Wie viele Helfer brauchen wir?","section":"helfer","speaker":"B"},{"text":"Einige am Eingang, zwei am Informationsstand und zusätzliche Personen für das Kinderprogramm.","section":"helfer","speaker":"A"},{"text":"Das klingt nach einer vernünftigen Lösung.","section":"helfer","speaker":"B"},{"text":"Wie könnten wir die Aufgaben möglichst effizient aufteilen?","section":"aufgabenverteilung","speaker":"A"},{"text":"Ich kann Poster und Flyer vorbereiten. Würdest du dann das Kulturzentrum kontaktieren und nach dem Raumplan fragen?","section":"aufgabenverteilung","speaker":"B"},{"text":"Ja, das übernehme ich gerne.","section":"aufgabenverteilung","speaker":"A"},{"text":"Dann können wir festhalten, dass wir mit Werbung, Lesungen, Kinderbereich, Ständen und einem Lageplan planen.","section":"abschluss","speaker":"A"},{"text":"Genau. So haben wir Werbung, Programm, Stände und Organisation abgedeckt.","section":"abschluss","speaker":"B"},{"text":"Perfekt, dann haben wir einen guten Plan.","section":"abschluss","speaker":"A"}],"schema_version":3,"moegliche_fragen":["Sollen die Besucher Eintritt zahlen?","Wie lange sollte die Messe dauern?","Was machen wir, wenn zu viele Besucher kommen?","Sollten wir auch Bücher für Kinder anbieten?","Wie finden wir genug Helfer?","Sollten wir ein kleines Café einrichten?","Brauchen wir Technik wie Mikrofon und Beamer?"],"moegliche_antworten_ideen":["Der Eintritt sollte frei sein, damit möglichst viele Menschen kommen.","Am besten zwei Tage, zum Beispiel Samstag und Sonntag.","Wir könnten Ordner am Eingang einsetzen und die Besucherzahl im Blick behalten.","Ein Büchertausch oder ein Lesewettbewerb könnte ein zusätzlicher Anziehungspunkt sein.","Wir könnten Freiwillige aus Schulen und Sprachkursen fragen.","Ein kleines Café im Foyer lädt zum Bleiben und Lesen ein.","Für Lesungen brauchen wir auf jeden Fall ein Mikrofon und genug Stühle."]}$q$::jsonb
where not exists (select 1 from public.muendlich_materials where teil = 3 and level = 'TELC_B2' and title = $q$Buchmesse im Kulturzentrum mitplanen$q$)
returning id, title, is_unassigned_center, position;